function clonePosition(m,cx,cy){if(['line','arrow','distance'].includes(m.type)){m.x1=cx(m.x1);m.x2=cx(m.x2);m.y1=cy(m.y1);m.y2=cy(m.y2);}else if(['polygon','polyline','perimeter','area'].includes(m.type)){m.pts?.forEach(p=>{p.x=cx(p.x);p.y=cy(p.y);});}else{const a={x:m.x,y:m.y},b={x:m.x+m.w,y:m.y+m.h},c=[{x:cx(a.x),y:cy(a.y)},{x:cx(b.x),y:cy(b.y)}];m.x=Math.min(c[0].x,c[1].x);m.y=Math.min(c[0].y,c[1].y);m.w=Math.abs(c[1].x-c[0].x);m.h=Math.abs(c[1].y-c[0].y);if(m.tip){m.tip.x=cx(m.tip.x);m.tip.y=cy(m.tip.y);}}}
