 const results=[];for(let g=0;g<groups.length;g++){const pages=groups[g],res=await createPDFSubset(pages,{annotations:policy});const fname=groups.length===1?output:ext(output,`_${String(g+1).padStart(2,'0')}`);results.push({name:fname,bytes:res.bytes,pairs:res.pairs.map((p,j)=>({...p,sourcePageId:idArray(docNow())[pages[j]]}))});}
