function splitGroups(){const n=state.pageSizes.length,mode=$o('pmSplitMode').value,groups=[];if(mode==='every'){const step=Number($o('pmSplitEvery').value);if(!Number.isInteger(step)||step<1)throw Error('Enter a positive number of pages for each output PDF.');for(let i=0;i<n;i+=step)groups.push(Array.from({length:Math.min(step,n-i)},(_,j)=>i+j));}else if(mode==='before'){let breaks=rangeParse($o('pmSplitAt').value,n).filter(i=>i>0).sort((a,b)=>a-b);const steps=[0,...breaks,n];for(let i=0;i<steps.length-1;i++)if(steps[i+1]>steps[i])groups.push(Array.from({length:steps[i+1]-steps[i]},(_,j)=>steps[i]+j));}else{const parts=String($o('pmCustomRanges').value).split(';');for(const p of parts){const a=rangeParse(p,n);if(a.length)groups.push(a);}const uniq=new Set(groups.flat());if(uniq.size!==groups.flat().length)throw Error('Split ranges overlap. Each page must occur in at most one output.');if(uniq.size!==n)throw Error(`Split ranges include ${uniq.size} of ${n} pages. Include every page or choose Extraction.`);}if(!groups.length)throw Error('No split groups found.');return groups;}
