function pageTileSize(i){const {w,h}=state.pageSizes[i]||{w:595,h:842};const ratio=w/h;const iso={A0:[2384,3370],A1:[1684,2384],A2:[1191,1684],A3:[842,1191],A4:[595,842],A5:[420,595]};const long=Math.max(w,h),short=Math.min(w,h);let label='Custom';for(const [name,[a,b]] of Object.entries(iso)){if(Math.abs(long-b)/b<.035&&Math.abs(short-a)/a<.035){label=name;break;}}return `${label} · ${Math.round(w)}×${Math.round(h)} pt`;}
